import {topics,questions,sources} from './content.js';
import {score,mastery,filtered,shuffle,remaining,readState,fresh} from './engine.js';
let localStore;try{localStore=localStorage;}catch{localStore={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable');}};}
let state=readState(localStore),view='home',selected='percentages',subject='all',search='',step=0,session=null,timer=null,demoRun=null;
const $=s=>document.querySelector(s), app=$('#app');
const bi=(en,hi)=>state.locale==='hi'?hi:en,tx=o=>o[state.locale]??o.en;
const icons={home:'▦',learn:'◈',practice:'✓',exam:'◷',progress:'▥',sources:'▤'};
const labels=()=>({home:bi('My dashboard','मेरा डैशबोर्ड'),learn:bi('Explore topics','विषय खोजें'),practice:bi('Practice quizzes','अभ्यास क्विज़'),exam:bi('Timed practice','समयबद्ध अभ्यास'),progress:bi('My progress','मेरी प्रगति'),sources:bi('Syllabus & sources','पाठ्यक्रम और स्रोत')});
const examNames=()=>({all:bi('All exams','सभी परीक्षाएं'),ssc:'SSC',banking:bi('Banking','बैंकिंग'),railways:bi('Railways','रेलवे'),insurance:bi('Insurance','बीमा')});
function save(){try{localStore.setItem('aptitudelab-v1',JSON.stringify(state));$('#storage-note')?.remove();}catch{if(!$('#storage-note'))app.insertAdjacentHTML('beforeend',`<div id="storage-note" role="alert" class="toast">${bi('Storage unavailable. Progress will last for this visit only.','स्टोरेज उपलब्ध नहीं है। प्रगति केवल इस सत्र तक रहेगी।')}</div>`);}}
const totalCorrect=()=>state.attempts.filter(a=>a.correct).length;
const accuracy=()=>state.attempts.length?Math.round(totalCorrect()/state.attempts.length*100):0;
function nav(v){if(session&&!session.done&&v!=='session'){if(!confirm(bi('Leave this practice? Unsubmitted answers will be lost.','अभ्यास छोड़ें? जमा नहीं किए उत्तर खो जाएंगे।')))return;session=null;}clearInterval(timer);clearInterval(demoRun);view=v;step=0;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.documentElement.lang=state.locale;const l=labels();app.innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-nav="home"><img src="icon.svg" alt=""><span>Aptitude<span class="brand-light">Lab</span><small>${bi('UNDERSTAND. PRACTICE. GROW.','समझें। अभ्यास करें। आगे बढ़ें।')}</small></span></a><div class="nav-label">${bi('YOUR LEARNING SPACE','आपका अध्ययन क्षेत्र')}</div><nav aria-label="${bi('Main navigation','मुख्य नेविगेशन')}">${['home','learn','practice','exam','progress'].map(v=>`<button class="nav-item ${view===v||(view==='lesson'&&v==='learn')?'active':''}" data-nav="${v}" ${view===v?'aria-current="page"':''}><span>${icons[v]}</span>${l[v]}</button>`).join('')}</nav><div class="side-bottom"><div class="little-lab">✦<strong>${bi('Small steps. Big breakthroughs.','छोटे कदम। बड़ी सफलता।')}</strong><p>${bi('A little curiosity goes a long way.','थोड़ी जिज्ञासा बहुत आगे ले जाती है।')}</p></div><button class="nav-item ${view==='sources'?'active':''}" data-nav="sources"><span>▤</span>${l.sources}</button><div class="local-tag">◉ ${bi('Progress saved on this device','प्रगति इस डिवाइस पर सुरक्षित')}</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${bi('Your workspace','आपका अध्ययन क्षेत्र')} <span>/</span> <strong>${l[view]||bi('Learning lab','अध्ययन लैब')}</strong></div><div class="top-controls"><label class="sr-only" for="exam-filter">${bi('Exam focus','परीक्षा फ़िल्टर')}</label><select id="exam-filter">${Object.entries(examNames()).map(([k,v])=>`<option value="${k}" ${state.exam===k?'selected':''}>${v}</option>`).join('')}</select><button id="language" class="language" aria-label="${bi('Switch to Hindi','अंग्रेज़ी में बदलें')}">${bi('हिंदी','English')}</button><div class="avatar" aria-label="${bi('Local learner profile','स्थानीय विद्यार्थी प्रोफ़ाइल')}">L</div></div></header><main id="main" tabindex="-1">${body()}</main><footer>AptitudeLab <span>·</span> ${bi('Made for your next breakthrough.','आपकी अगली सफलता के लिए।')} <button data-nav="sources">${bi('Content & sources','सामग्री और स्रोत')}</button></footer></div>`;
app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();nav(b.dataset.nav);});$('#language').onclick=()=>{state.locale=state.locale==='en'?'hi':'en';save();render();};$('#exam-filter').onchange=e=>{if(session&&!session.done){e.target.value=state.exam;alert(bi('Finish or leave your active practice before changing the exam filter.','परीक्षा फ़िल्टर बदलने से पहले सक्रिय अभ्यास पूरा करें या छोड़ें।'));return;}state.exam=e.target.value;save();render();};bind();if(view==='lesson')bindDemo();if(view==='session'&&session?.timed&&!session.done)runTimer();}
function body(){switch(view){case'home':return home();case'learn':case'practice':return library();case'lesson':return lesson();case'exam':return examSetup();case'session':return session.done?results():quiz();case'progress':return progress();case'sources':return sourcePage();default:return home();}}
const heading=(eyebrow,title,desc)=>`<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>`;
function stats(){return `<div class="stats"><article><span class="stat-icon purple">◈</span><div><strong>${state.lessons.length}<small> / ${topics.length}</small></strong><p>${bi('Lessons explored','सीखे गए पाठ')}</p></div></article><article><span class="stat-icon teal">✓</span><div><strong>${state.attempts.length}</strong><p>${bi('Questions attempted','प्रयास किए प्रश्न')}</p></div></article><article><span class="stat-icon orange">◎</span><div><strong>${accuracy()}<small>%</small></strong><p>${bi('Practice accuracy','अभ्यास सटीकता')}</p></div></article><article><span class="stat-icon pink">✦</span><div><strong>${topics.filter(t=>mastery(state.attempts,t.id)>=80).length}</strong><p>${bi('Topics at 80%+','80%+ वाले विषय')}</p></div></article></div>`;}
function home(){const pool=filtered(topics,state.exam),next=pool.find(t=>!state.lessons.includes(t.id))||pool[0];return `${heading(bi('A LITTLE BETTER, EVERY DAY','हर दिन, थोड़ा बेहतर'),bi('Make concepts <em>click.</em>','अवधारणाएं <em>समझें।</em>'),bi('Less memorising. More understanding. Your next breakthrough starts here.','कम रटें। ज्यादा समझें। आपकी अगली सफलता यहीं से शुरू होती है।'))}<section class="hero"><div class="hero-copy"><span class="pill">✦ ${bi('LEARN BY DOING','करके सीखें')}</span><h2>${bi('Don’t just solve it.<br>See how it works.','केवल हल न करें।<br>उसका तर्क भी देखें।')}</h2><p>${bi('Move a slider. Spot a pattern. Build an intuition.<br>Aptitude feels different when you’re in control.','स्लाइडर चलाएं। पैटर्न पहचानें। समझ विकसित करें।<br>अपने हाथों से सीखना अलग अनुभव है।')}</p><button class="primary" data-lesson="${next.id}">${bi('Enter the learning lab','लर्निंग लैब में जाएं')} <span>✦</span></button><div class="hero-meta">${bi('6 interactive labs','6 इंटरैक्टिव लैब')} <i></i> ${bi('English + हिंदी','हिंदी + English')} <i></i> ${bi('At your pace','अपनी गति से')}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="float-tag tag1">a : b <span>✦</span></div><div class="art-card"><div class="art-card-top"><span>THE PERCENTAGE LAB</span><span>•••</span></div><div class="art-number">25<span>%</span></div><div class="mini-grid">${Array.from({length:40},(_,i)=>`<i class="${i<10?'filled':''}"></i>`).join('')}</div><div class="art-slider"><i></i></div><small>A little change. A clear picture.</small></div><div class="float-tag tag2">✓ <span>Concept unlocked</span></div><span class="spark sp1">✧</span><span class="spark sp2">✦</span></div></section>${stats()}<section class="section"><div class="section-top"><div><h2>${bi('Find your next “aha!”','अपनी अगली नई समझ खोजें')}</h2><p>${bi('Pick a topic. Play with the idea. Put it into practice.','विषय चुनें। विचार को आजमाएं। अभ्यास करें।')}</p></div><button class="text-button" data-nav="learn">${bi('View all topics','सभी विषय देखें')}</button></div><div class="topic-grid">${pool.slice(0,3).map(card).join('')}</div></section><section class="bottom-grid"><article class="challenge"><div class="challenge-symbol">◷</div><div><span class="eyebrow">${bi('READY FOR A CHALLENGE?','चुनौती के लिए तैयार?')}</span><h3>${bi('Bring it all together.','सब कुछ साथ आजमाएं।')}</h3><p>${bi('A mixed, timed drill to build accuracy under pressure.','दबाव में सटीकता के लिए मिश्रित समयबद्ध अभ्यास।')}</p><button class="dark-button" data-nav="exam">${bi('Set up timed practice','समयबद्ध अभ्यास बनाएं')}</button></div></article><article class="path-note"><span>✧</span><h3>${bi('Understanding comes first.','समझ सबसे पहले।')}</h3><p>${bi('Explore → Guided example → Quick quiz.<br>One clear concept at a time.','खोजें → निर्देशित उदाहरण → क्विज़।<br>एक बार में एक स्पष्ट अवधारणा।')}</p><button class="text-button" data-nav="progress">${bi('See your learning journey','अपनी अध्ययन यात्रा देखें')}</button></article></section>`;}
function card(t){const m=mastery(state.attempts,t.id),count=state.attempts.filter(a=>a.topic===t.id).length;return `<article class="topic-card"><div class="card-top"><span class="topic-icon ${t.color}">${t.icon}</span><span class="tag">${t.subject==='quant'?bi('QUANTITATIVE','गणित'):bi('REASONING','तर्कशक्ति')}</span></div><h3>${tx(t.title)}</h3><p>${tx(t.desc)}</p><div class="card-meta">${t.minutes} ${bi('min lesson','मिनट का पाठ')} <span>·</span> 5 ${bi('questions','प्रश्न')}</div><div class="mastery-line"><span>${count?bi('Recent accuracy','हाल की सटीकता'):bi('Ready to explore','सीखना शुरू करें')}</span><strong>${count?m+'%':bi('New','नया')}</strong></div><div class="bar"><i style="width:${m}%"></i></div><div class="card-actions"><button class="${view==='practice'?'secondary':'soft-button'}" data-lesson="${t.id}">${state.lessons.includes(t.id)?bi('Revisit lab','लैब दोहराएं'):bi('Explore lab','लैब खोलें')}</button><button class="${view==='practice'?'soft-button':'secondary'}" data-practice="${t.id}">${bi('Quiz','क्विज़')}</button></div></article>`;}
function library(){const pool=filtered(topics,state.exam,search,subject);return `${heading(bi('YOUR CONCEPT TOOLKIT','आपके अध्ययन उपकरण'),view==='practice'?bi('A little practice. <em>A lot of progress.</em>','थोड़ा अभ्यास। <em>बड़ी प्रगति।</em>'):bi('Curiosity looks good <em>on you.</em>','अपनी जिज्ञासा को <em>जगाएं।</em>'),bi('Original questions. Clear explanations. Learn the why behind every answer.','मौलिक प्रश्न। स्पष्ट व्याख्या। हर उत्तर के पीछे का कारण सीखें।'))}<div class="library-tools"><div class="tabs" role="group" aria-label="${bi('Subject filter','विषय फ़िल्टर')}">${[['all',bi('All topics','सभी विषय')],['quant',bi('Quantitative','गणित')],['reason',bi('Reasoning','तर्कशक्ति')]].map(([v,n])=>`<button data-subject="${v}" class="${subject===v?'active':''}" aria-pressed="${subject===v}">${n}</button>`).join('')}</div><label class="search"><span>⌕</span><input id="topic-search" type="search" placeholder="${bi('Search a topic…','विषय खोजें…')}" aria-label="${bi('Search topics','विषय खोजें')}"></label></div><div id="topic-results" class="topic-grid">${pool.map(card).join('')||`<p class="empty">${bi('No topics match. Try another search or exam filter.','कोई विषय नहीं मिला। अन्य खोज या परीक्षा फ़िल्टर आजमाएं।')}</p>`}</div><p class="muted scope-note">${bi('Foundation MVP: 6 topics and 30 original questions. Exam filters show relevant practice paths; they do not represent complete syllabi.','प्रारंभिक संस्करण: 6 विषय और 30 मौलिक प्रश्न। परीक्षा फ़िल्टर प्रासंगिक अभ्यास दिखाते हैं; ये संपूर्ण पाठ्यक्रम नहीं हैं।')}</p>`;}
function lesson(){const t=topics.find(t=>t.id===selected);return `<button class="back text-button" data-nav="learn">‹ ${bi('All topics','सभी विषय')}</button>${heading(bi('THE LEARNING LAB','लर्निंग लैब'),tx(t.title),tx(t.desc))}<div class="lesson-layout"><div><section class="panel"><div class="section-top"><h2>${bi('Make it tangible','इसे करके देखें')}</h2><span class="tag teal">${bi('INTERACTIVE','इंटरैक्टिव')}</span></div><p>${tx(t.concept)}</p><div class="formula">${t.formula}</div>${demoMarkup(t.id)}</section><section class="panel guided"><span class="eyebrow">${bi('LET’S WORK THROUGH ONE','एक उदाहरण साथ हल करें')}</span><h2>${bi('Guided example','निर्देशित उदाहरण')}</h2><ol class="steps">${tx(t.steps).slice(0,step+1).map((s,i)=>`<li><span>${i+1}</span><p>${s}</p></li>`).join('')}</ol>${step<tx(t.steps).length-1?`<button class="soft-button" id="next-step">${bi('Reveal next step','अगला चरण देखें')}</button>`:`<div class="feedback correct">✓ ${bi('Now try the idea for yourself.','अब इस विचार का स्वयं अभ्यास करें।')}</div><button id="complete-lesson" class="primary">${bi('Complete lesson & take quiz','पाठ पूरा करें और क्विज़ लें')}</button>`}</section></div><aside class="lesson-aside panel"><span class="topic-icon ${t.color}">${t.icon}</span><h3>${bi('Your learning loop','आपका अध्ययन चक्र')}</h3><p>◈ ${bi('Explore the concept','अवधारणा खोजें')}</p><p>▤ ${bi('Follow an example','उदाहरण समझें')}</p><p>✓ ${bi('Check your understanding','अपनी समझ जांचें')}</p><hr><p class="muted">${bi('Take your time. Try different values and watch what changes.','समय लें। अलग मान आजमाएं और परिवर्तन देखें।')}</p><button class="secondary" data-practice="${t.id}">${bi('Go straight to quiz','सीधे क्विज़ लें')}</button></aside></div>`;}
const range=(id,label,min,max,value,unit='')=>`<label class="range-label" for="${id}"><span>${label}</span><output id="${id}-out">${value}${unit}</output></label><input id="${id}" type="range" min="${min}" max="${max}" value="${value}">`;
function demoMarkup(id){switch(id){case'percentages':return `<div class="demo">${range('pct',bi('Percentage','प्रतिशत'),0,100,25,'%')}${range('whole',bi('Whole / base','पूरी मात्रा / आधार'),100,1000,400)}<div class="percent-demo"><div class="hundred-grid" id="hundred-grid">${Array.from({length:100},()=>'<i></i>').join('')}</div><div><span class="muted">${bi('THE PART','भाग')}</span><strong id="part-value" class="big-value"></strong><p id="pct-equation"></p><p class="muted">${bi('Each square is 1% of the whole.','हर वर्ग पूरी मात्रा का 1% है।')}</p></div></div></div>`;case'ratios':return `<div class="demo">${range('ratio-a',bi('Part A','भाग A'),1,8,2)}${range('ratio-b',bi('Part B','भाग B'),1,8,3)}<div id="ratio-blocks" class="ratio-blocks"></div><div class="demo-answer" id="ratio-answer"></div><p class="muted">${bi('The total stays at 600. Change the ratio to redistribute the whole.','कुल मात्रा 600 है। अनुपात बदलने पर हिस्से बदलते हैं।')}</p></div>`;case'work':return `<div class="demo">${range('worker-a',bi('A alone (days)','A अकेला (दिन)'),2,24,12)}${range('worker-b',bi('B alone (days)','B अकेला (दिन)'),2,24,6)}<div class="work-tracks"><div><span>A</span><div class="bar"><i id="wa"></i></div></div><div><span>B</span><div class="bar teal-bar"><i id="wb"></i></div></div><div><span>A+B</span><div class="bar orange-bar"><i id="wab"></i></div></div></div><div id="work-answer" class="demo-answer"></div><button class="secondary" id="animate-work">${bi('Simulate one day','एक दिन का अनुकरण')}</button><p class="muted">${bi('Bars show the fraction of the job completed in one day.','पट्टियां एक दिन में पूरे किए काम का भाग दिखाती हैं।')}</p></div>`;case'speed':return `<div class="demo">${range('speed-value',bi('Speed (km/h)','चाल (किमी/घंटा)'),10,120,60)}${range('time-value',bi('Time (hours)','समय (घंटे)'),1,5,2)}<div class="road"><span id="car">▰</span><i></i><small>0 km</small><small id="road-end"></small></div><div class="demo-answer" id="distance-answer"></div><button id="animate-speed" class="secondary">${bi('Play journey','यात्रा चलाएं')}</button><p class="muted">${bi('Animation is illustrative; distance is calculated from your values.','एनीमेशन उदाहरण है; दूरी आपके मानों से गणना की जाती है।')}</p></div>`;case'series':return `<div class="demo">${range('series-start',bi('Starting number','शुरू की संख्या'),1,12,3)}${range('series-step',bi('Add each time','हर बार जोड़ें'),1,10,4)}<div id="series-terms" class="series-terms"></div><button id="reveal-series" class="secondary">${bi('Reveal next term','अगला पद देखें')}</button><div id="series-answer" class="demo-answer"></div></div>`;case'syllogisms':return `<div class="demo"><label for="logic-rule">${bi('Choose a statement','कथन चुनें')}</label><select id="logic-rule"><option value="all">${bi('All A are B','सभी A, B हैं')}</option><option value="some">${bi('Some A are B','कुछ A, B हैं')}</option><option value="none">${bi('No A are B','कोई A, B नहीं है')}</option></select><div class="venn" id="venn"><div class="set set-b"><span>B</span></div><div class="set set-a"><span>A</span></div><i class="exist">×</i></div><div id="logic-answer" class="demo-answer" aria-live="polite"></div></div>`;}}
function bindDemo(){const val=id=>Number($('#'+id).value);let revealed=false;function update(){if(selected==='percentages'){const p=val('pct'),w=val('whole');$('#pct-out').textContent=p+'%';$('#whole-out').textContent=w;$('#hundred-grid').querySelectorAll('i').forEach((e,i)=>e.classList.toggle('filled',i<p));$('#part-value').textContent=+(w*p/100).toFixed(2);$('#pct-equation').textContent=`${p}% × ${w} = ${+(w*p/100).toFixed(2)}`;}if(selected==='ratios'){const a=val('ratio-a'),b=val('ratio-b');$('#ratio-a-out').textContent=a;$('#ratio-b-out').textContent=b;$('#ratio-blocks').innerHTML=Array.from({length:a+b},(_,i)=>`<span class="${i<a?'ra':'rb'}">${i<a?'A':'B'}</span>`).join('');$('#ratio-answer').textContent=`A:B = ${a}:${b} · A = ${(600*a/(a+b)).toFixed(1)} · B = ${(600*b/(a+b)).toFixed(1)}`;}if(selected==='work'){const a=val('worker-a'),b=val('worker-b');$('#worker-a-out').textContent=a;$('#worker-b-out').textContent=b;$('#wa').style.width=100/a+'%';$('#wb').style.width=100/b+'%';$('#wab').style.width=(100/a+100/b)+'%';$('#work-answer').textContent=`1/${a} + 1/${b} = ${(1/a+1/b).toFixed(3)} ${bi('job/day','काम/दिन')} · ${bi('Together','साथ में')}: ${(1/(1/a+1/b)).toFixed(2)} ${bi('days','दिन')}`;}if(selected==='speed'){const s=val('speed-value'),t=val('time-value');$('#speed-value-out').textContent=s;$('#time-value-out').textContent=t;$('#distance-answer').textContent=`${s} km/h × ${t} h = ${s*t} km`;$('#road-end').textContent=s*t+' km';$('#car').style.left='0%';}if(selected==='series'){const s=val('series-start'),d=val('series-step');$('#series-start-out').textContent=s;$('#series-step-out').textContent=d;$('#series-terms').innerHTML=Array.from({length:5},(_,i)=>`<span>${i===4&&!revealed?'?':s+d*i}</span>`).join('');$('#series-answer').textContent=revealed?`${s+3*d} + ${d} = ${s+4*d}`:bi('What comes next? Predict it before revealing.','अगला पद क्या होगा? देखने से पहले अनुमान लगाएं।');}if(selected==='syllogisms'){const rule=$('#logic-rule').value;$('#venn').className='venn '+rule;$('#logic-answer').textContent=rule==='all'?bi('A is fully inside B. The reverse is not guaranteed. This alone does not prove any A exists.','A पूरी तरह B में है। उल्टा जरूरी नहीं। इससे अकेले A का अस्तित्व सिद्ध नहीं होता।'):rule==='some'?bi('× marks at least one member in the overlap. Some B are also A.','× साझा भाग में कम से कम एक सदस्य दर्शाता है। कुछ B भी A हैं।'):bi('A and B are disjoint. No member can belong to both.','A और B अलग हैं। कोई सदस्य दोनों में नहीं हो सकता।');}}
$('.demo').querySelectorAll('input,select').forEach(e=>e.oninput=()=>{revealed=false;update();});$('#reveal-series')?.addEventListener('click',()=>{revealed=true;update();});$('#animate-speed')?.addEventListener('click',()=>{const car=$('#car');car.getAnimations().forEach(a=>a.cancel());car.animate([{left:'0%'},{left:'calc(100% - 40px)'}],{duration:2400,fill:'forwards',easing:'linear'});});$('#animate-work')?.addEventListener('click',()=>{$('.work-tracks').querySelectorAll('.bar i').forEach(e=>e.animate([{width:'0%'},{width:e.style.width}],{duration:1200,easing:'ease-out'}));});update();}
function examSetup(){const count=questions.filter(q=>filtered(topics,state.exam).some(t=>t.id===q.topic)).length;return `${heading(bi('A LITTLE PRESSURE. A LOT OF LEARNING.','थोड़ा दबाव। ज्यादा सीखना।'),bi('Your practice. <em>Your pace.</em>','आपका अभ्यास। <em>आपकी गति।</em>'),bi('Build focus with an original mixed-topic drill.','मौलिक मिश्रित प्रश्नों से एकाग्रता बढ़ाएं।'))}<div class="setup-grid"><section class="panel"><h2>${bi('Create a timed drill','समयबद्ध अभ्यास बनाएं')}</h2><p>${bi('Questions are shuffled from the current exam filter. Answers and solutions appear after submission.','वर्तमान परीक्षा फ़िल्टर से प्रश्न यादृच्छिक क्रम में आते हैं। उत्तर और हल जमा करने के बाद दिखेंगे।')}</p><form id="exam-form"><label for="exam-count">${bi('Questions','प्रश्न')}</label><select id="exam-count"><option value="5">5</option><option value="10" selected>10</option><option value="15">15</option><option value="${count}">${bi('All','सभी')} (${count})</option></select><label for="exam-time">${bi('Time limit','समय सीमा')}</label><select id="exam-time"><option value="3">3 ${bi('minutes','मिनट')}</option><option value="5">5 ${bi('minutes','मिनट')}</option><option value="10" selected>10 ${bi('minutes','मिनट')}</option><option value="15">15 ${bi('minutes','मिनट')}</option></select><label for="exam-penalty">${bi('Wrong-answer penalty (per 1 mark)','गलत उत्तर की कटौती (प्रति 1 अंक)')}</label><select id="exam-penalty"><option value="0">${bi('No penalty','कोई कटौती नहीं')}</option><option value="0.25">−0.25</option><option value="0.3333333333333333">−1/3</option></select><div class="notice">${bi('Custom foundation drill, not a full official mock. The filter selects topics, not official section weights or exam rules.','यह बुनियादी कस्टम अभ्यास है, पूरी आधिकारिक मॉक परीक्षा नहीं। फ़िल्टर विषय चुनता है, आधिकारिक अनुभाग भार या नियम नहीं।')}</div><button class="primary" type="submit">${bi('Start timed practice','समयबद्ध अभ्यास शुरू करें')}</button></form></section><section class="panel setup-info"><span class="large-symbol">◷</span><h2>${bi('A clear head wins.','शांत मन से अभ्यास करें।')}</h2><ul><li>${bi('One mark for each correct answer.','हर सही उत्तर पर एक अंक।')}</li><li>${bi('Skip and revisit questions using the question palette.','प्रश्न सूची से प्रश्न छोड़ें और दोहराएं।')}</li><li>${bi('The timer keeps running in a background tab.','अन्य टैब पर जाने पर भी समय चलता रहता है।')}</li><li>${bi('Time up? Your current answers submit automatically.','समय समाप्त? वर्तमान उत्तर स्वतः जमा होंगे।')}</li><li>${bi('Active drills are not saved if you reload or close the page.','पेज रीलोड या बंद करने पर सक्रिय अभ्यास सुरक्षित नहीं रहेगा।')}</li></ul></section></div>`;}
function startQuiz(topic,timed=false,count=5,minutes=10,penalty=0){const pool=questions.filter(q=>topic?q.topic===topic:filtered(topics,state.exam).some(t=>t.id===q.topic));session={questions:timed?shuffle(pool).slice(0,count):pool,answers:{},checked:{},index:0,timed,penalty,done:false,started:Date.now(),deadline:Date.now()+minutes*60000,topic};view='session';render();window.scrollTo(0,0);}
function quiz(){const s=session,q=s.questions[s.index],checked=s.checked[q.id],picked=s.answers[q.id];return `<div class="quiz-heading"><div><span class="eyebrow">${s.timed?bi('TIMED DRILL','समयबद्ध अभ्यास'):bi('CHECK YOUR UNDERSTANDING','अपनी समझ जांचें')}</span><h1>${s.topic?tx(topics.find(t=>t.id===s.topic).title):bi('Mixed practice','मिश्रित अभ्यास')}</h1></div>${s.timed?`<div class="timer" role="timer" aria-label="${bi('Time remaining','शेष समय')}"><span>◷</span> <strong id="countdown"></strong></div>`:`<span class="pill">${bi('No timer. Just learning.','बिना समय सीमा। केवल सीखना।')}</span>`}</div><div class="quiz-layout"><section class="panel question-panel"><div class="question-meta"><span>${bi('Question','प्रश्न')} ${s.index+1} / ${s.questions.length}</span><span>${tx(topics.find(t=>t.id===q.topic).title)}</span></div><div class="bar"><i style="width:${(s.index+1)/s.questions.length*100}%"></i></div><h2>${tx(q.prompt)}</h2><div class="options" role="group" aria-label="${bi('Answer choices','उत्तर विकल्प')}">${q.options.map((o,i)=>`<button data-option="${i}" class="option ${picked===i?'selected':''} ${checked&&i===q.answer?'right':''} ${checked&&picked===i&&i!==q.answer?'wrong':''}" aria-pressed="${picked===i}" ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${tx(o)}${checked&&i===q.answer?'<b>✓</b>':''}</button>`).join('')}</div>${checked?`<div class="feedback ${picked===q.answer?'correct':'incorrect'}" role="status"><strong>${picked===q.answer?bi('✓ You’ve got it!','✓ सही समझा!'):bi('Let’s unpack that.','इसे समझते हैं।')}</strong><p>${bi('Correct answer','सही उत्तर')}: ${tx(q.options[q.answer])}</p><ol>${tx(q.steps).map(x=>`<li>${x}</li>`).join('')}</ol></div>`:''}<div class="question-actions"><button id="previous-question" class="secondary" ${s.index===0?'disabled':''}>${bi('Previous','पिछला')}</button>${!s.timed&&!checked?`<button class="primary" id="check-answer" ${picked===undefined?'disabled':''}>${bi('Check answer','उत्तर जांचें')}</button>`:`<button class="primary" id="next-question">${s.index===s.questions.length-1?bi('Review & finish','देखें और पूरा करें'):bi('Next question','अगला प्रश्न')}</button>`}</div></section><aside class="panel palette"><h3>${bi('Your questions','आपके प्रश्न')}</h3><div class="palette-grid">${s.questions.map((q,i)=>`<button data-question="${i}" aria-label="${bi('Question','प्रश्न')} ${i+1}${s.answers[q.id]!==undefined?bi(', answered',', उत्तर चुना'):''}" class="${i===s.index?'current':''} ${s.answers[q.id]!==undefined?'answered':''}">${i+1}</button>`).join('')}</div><p class="muted">${Object.keys(s.answers).length} / ${s.questions.length} ${bi('answered','उत्तर चुने')}</p><button id="finish-quiz" class="secondary">${bi('Submit practice','अभ्यास जमा करें')}</button><p class="muted">${s.timed?bi('Solutions unlock when you submit.','जमा करने पर हल दिखेंगे।'):bi('Check answers for immediate explanations.','तुरंत व्याख्या के लिए उत्तर जांचें।')}</p><div id="submit-confirm" hidden class="notice"></div></aside></div>`;}
function record(q){if(session.checked[q.id]||session.answers[q.id]===undefined)return;session.checked[q.id]=true;state.attempts.push({topic:q.topic,id:q.id,correct:session.answers[q.id]===q.answer,at:Date.now()});save();}
function submit(auto=false){if(session.done)return;clearInterval(timer);for(const q of session.questions)record(q);session.done=true;session.auto=auto;session.result=score(session.questions,session.answers,session.penalty);state.sessions.push({...session.result,at:Date.now(),timed:session.timed,count:session.questions.length});save();render();window.scrollTo(0,0);}
function askSubmit(){const skipped=session.questions.filter(q=>session.answers[q.id]===undefined).length;const el=$('#submit-confirm');el.hidden=false;el.innerHTML=`<p>${skipped?bi(`${skipped} unanswered. Submit anyway?`,`${skipped} प्रश्न अनुत्तरित। फिर भी जमा करें?`):bi('Ready to submit your answers?','उत्तर जमा करने के लिए तैयार?')}</p><button class="primary" id="confirm-submit">${bi('Submit now','अभी जमा करें')}</button> <button class="text-button" id="cancel-submit">${bi('Keep working','अभ्यास जारी रखें')}</button>`;$('#confirm-submit').onclick=()=>submit();$('#cancel-submit').onclick=()=>el.hidden=true;}
function runTimer(){clearInterval(timer);function tick(){if(!session||session.done)return;const seconds=remaining(session.deadline);const el=$('#countdown');if(el)el.textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;$('.timer')?.classList.toggle('urgent',seconds<60);if(seconds===0)submit(true);}tick();if(!session.done)timer=setInterval(tick,500);}
function results(){const s=session,r=s.result;return `${heading(bi('ANOTHER STEP FORWARD','एक और कदम आगे'),r.accuracy>=80?bi('That’s a <em>breakthrough.</em>','यह है <em>नई सफलता।</em>'):bi('Every answer teaches <em>something.</em>','हर उत्तर <em>कुछ सिखाता है।</em>'),s.auto?bi('Time is up. Your answers were submitted automatically.','समय समाप्त। उत्तर स्वतः जमा हो गए।'):bi('Take a moment to understand what worked and what to revisit.','समझें कि क्या सही हुआ और किसे दोहराना है।'))}<div class="result-stats"><article><strong>${r.marks}<small> / ${s.questions.length}</small></strong><span>${bi('Score','अंक')}</span></article><article><strong>${r.correct}</strong><span>${bi('Correct','सही')}</span></article><article><strong>${r.wrong}</strong><span>${bi('Incorrect','गलत')}</span></article><article><strong>${r.skipped}</strong><span>${bi('Skipped','छोड़े')}</span></article></div><div class="result-actions"><button class="primary" id="retry-quiz">${bi('Practise again','फिर अभ्यास करें')}</button><button class="secondary" data-nav="progress">${bi('View progress','प्रगति देखें')}</button></div><h2>${bi('The thinking behind each answer','हर उत्तर के पीछे का तर्क')}</h2><p class="muted">${bi('Accuracy is based on attempted questions. Skipped questions receive zero marks.','सटीकता प्रयास किए प्रश्नों पर आधारित है। छोड़े प्रश्नों पर शून्य अंक हैं।')}</p>${s.questions.map((q,i)=>`<details class="panel solution" ${s.answers[q.id]!==q.answer?'open':''}><summary><span class="solution-status ${s.answers[q.id]===q.answer?'correct':'incorrect'}">${s.answers[q.id]===q.answer?'✓':s.answers[q.id]===undefined?'—':'×'}</span><span>${i+1}. ${tx(q.prompt)}</span><span>⌄</span></summary><div class="solution-body"><p>${bi('Your answer','आपका उत्तर')}: <strong>${s.answers[q.id]===undefined?bi('Skipped','छोड़ा'):tx(q.options[s.answers[q.id]])}</strong></p><p>${bi('Correct answer','सही उत्तर')}: <strong>${tx(q.options[q.answer])}</strong></p><ol>${tx(q.steps).map(x=>`<li>${x}</li>`).join('')}</ol><button class="text-button" data-lesson="${q.topic}">${bi('Revisit this concept','यह अवधारणा दोहराएं')}</button></div></details>`).join('')}`;}
function progress(){const attempted=topics.filter(t=>state.attempts.some(a=>a.topic===t.id));return `${heading(bi('YOUR EFFORT, MADE VISIBLE','आपकी मेहनत, आपके सामने'),bi('Progress over <em>perfection.</em>','पूर्णता से पहले <em>प्रगति।</em>'),bi('A real picture of your learning, one concept at a time.','आपकी सीखने की वास्तविक तस्वीर, एक अवधारणा के साथ।'))}${stats()}<section class="panel"><h2>${bi('Topic mastery','विषय पर पकड़')}</h2><p>${bi('Mastery is accuracy over your last 10 attempted answers per topic. Repeated questions count; this is a practice signal, not a predicted exam score.','हर विषय के अंतिम 10 प्रयासों की सटीकता पर पकड़ आधारित है। दोहराए प्रश्न भी गिने जाते हैं; यह अभ्यास संकेत है, अनुमानित परीक्षा अंक नहीं।')}</p>${topics.map(t=>{const n=state.attempts.filter(a=>a.topic===t.id).length,m=mastery(state.attempts,t.id);return `<div class="mastery-row"><span class="topic-icon ${t.color}">${t.icon}</span><div><strong>${tx(t.title)}</strong><small>${n} ${bi('attempts','प्रयास')} · ${state.lessons.includes(t.id)?bi('Lesson completed','पाठ पूरा'):bi('Lesson to explore','पाठ सीखना बाकी')}</small><div class="bar"><i style="width:${m}%"></i></div></div><strong>${n?m+'%':'—'}</strong><button class="secondary" data-practice="${t.id}">${bi('Practise','अभ्यास')}</button></div>`;}).join('')}</section>${!attempted.length?`<div class="notice">${bi('Your journey starts with one question. Try a topic quiz to see progress here.','आपकी यात्रा एक प्रश्न से शुरू होती है। प्रगति देखने के लिए क्विज़ आजमाएं।')}</div>`:''}<section class="panel"><h2>${bi('Recent practice','हाल का अभ्यास')}</h2>${state.sessions.length?`<div class="table-wrap"><table><thead><tr><th>${bi('Date','तारीख')}</th><th>${bi('Mode','प्रकार')}</th><th>${bi('Score','अंक')}</th><th>${bi('Accuracy','सटीकता')}</th></tr></thead><tbody>${state.sessions.slice(-10).reverse().map(s=>`<tr><td>${new Date(s.at).toLocaleDateString(state.locale==='hi'?'hi-IN':'en-IN')}</td><td>${s.timed?bi('Timed drill','समयबद्ध अभ्यास'):bi('Topic quiz','विषय क्विज़')}</td><td>${s.marks} / ${s.count}</td><td>${s.accuracy}%</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted">${bi('Completed quizzes will appear here.','पूरे किए क्विज़ यहां दिखेंगे।')}</p>`}</section><div class="data-actions"><button class="secondary" id="export-progress">${bi('Download my progress','मेरी प्रगति डाउनलोड करें')}</button><button class="text-button danger" id="reset-progress">${bi('Reset local progress','स्थानीय प्रगति मिटाएं')}</button></div>`;}
function sourcePage(){return `${heading(bi('BUILT ON CLEAR FOUNDATIONS','स्पष्ट आधार पर निर्मित'),bi('Know what you’re <em>practising.</em>','जानें कि आप क्या <em>अभ्यास कर रहे हैं।</em>'),bi('Original learning content, informed by official exam notices.','आधिकारिक परीक्षा सूचनाओं से निर्देशित मौलिक अध्ययन सामग्री।'))}<section class="panel"><h2>${bi('What this MVP covers','इस संस्करण में क्या है')}</h2><p>${bi('Six foundation topics across quantitative aptitude and reasoning. Every question and explanation is original; none is presented as a previous-year question. Filters organise broad study paths for SSC, banking, railways and insurance.','गणित और तर्कशक्ति के छह बुनियादी विषय। हर प्रश्न और व्याख्या मौलिक है; कोई प्रश्न पिछले वर्ष का नहीं बताया गया है। फ़िल्टर SSC, बैंकिंग, रेलवे और बीमा के अध्ययन मार्ग व्यवस्थित करते हैं।')}</p><p>${bi('This is not complete exam preparation: English, general awareness, advanced mathematics, data interpretation and several reasoning topics are not yet included. Timed drills use your chosen settings, not official exam formats.','यह संपूर्ण परीक्षा तैयारी नहीं है: अंग्रेज़ी, सामान्य जागरूकता, उच्च गणित, आंकड़ा विश्लेषण और कई तर्कशक्ति विषय अभी शामिल नहीं हैं। समयबद्ध अभ्यास आपके चुने नियमों का प्रयोग करते हैं, आधिकारिक प्रारूप का नहीं।')}</p><p class="muted">${bi('Sources reviewed: 23 November 2026. Always use the latest official notice for eligibility, syllabus and examination rules.','स्रोत समीक्षा: 23 नवंबर 2026। पात्रता, पाठ्यक्रम और परीक्षा नियमों के लिए नवीनतम आधिकारिक सूचना देखें।')}</p></section><div class="source-grid">${sources.map(s=>`<article class="panel"><span class="eyebrow">${bi('OFFICIAL SOURCE','आधिकारिक स्रोत')}</span><h3>${s.name}</h3><p>${tx(s.note)}</p><a class="text-button" href="${s.url}" target="_blank" rel="noopener noreferrer">${bi('Read official source','आधिकारिक स्रोत पढ़ें')} ↗</a></article>`).join('')}</div><section class="panel"><h2>${bi('Your data stays with you','आपका डेटा आपके पास')}</h2><p>${bi('Lessons, answer history, language and exam preferences are stored locally in this browser. There is no account or cloud sync in this MVP. Download your progress from My progress.','पाठ, उत्तर इतिहास, भाषा और परीक्षा वरीयताएं इसी ब्राउज़र में स्थानीय रूप से रहती हैं। इस संस्करण में खाता या क्लाउड सिंक नहीं है। मेरी प्रगति से डेटा डाउनलोड करें।')}</p><a href="https://github.com/invincy/aptitudelab" target="_blank" rel="noopener noreferrer" class="text-button">${bi('Project on GitHub','GitHub पर प्रोजेक्ट')}</a></section>`;}
function bind(){app.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{selected=b.dataset.lesson;nav('lesson');});app.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>startQuiz(b.dataset.practice));app.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;render();});if($('#topic-search')){$('#topic-search').value=search;$('#topic-search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#topic-search').focus();$('#topic-search').setSelectionRange(pos,pos);};}$('#next-step')?.addEventListener('click',()=>{step++;render();});$('#complete-lesson')?.addEventListener('click',()=>{if(!state.lessons.includes(selected))state.lessons.push(selected);save();startQuiz(selected);});$('#exam-form')?.addEventListener('submit',e=>{e.preventDefault();startQuiz(null,true,+$('#exam-count').value,+$('#exam-time').value,+$('#exam-penalty').value);});app.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(session.checked[session.questions[session.index].id])return;session.answers[session.questions[session.index].id]=+b.dataset.option;render();});app.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{session.index=+b.dataset.question;render();});$('#check-answer')?.addEventListener('click',()=>{record(session.questions[session.index]);render();});$('#previous-question')?.addEventListener('click',()=>{session.index--;render();});$('#next-question')?.addEventListener('click',()=>{if(session.index===session.questions.length-1)askSubmit();else{session.index++;render();}});$('#finish-quiz')?.addEventListener('click',askSubmit);$('#retry-quiz')?.addEventListener('click',()=>startQuiz(session.topic,session.timed,session.questions.length,(session.deadline-session.started)/60000,session.penalty));$('#export-progress')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='aptitudelab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('#reset-progress')?.addEventListener('click',()=>{if(confirm(bi('Permanently clear progress saved in this browser? Download it first if needed.','इस ब्राउज़र में सुरक्षित प्रगति स्थायी रूप से मिटाएं? जरूरत हो तो पहले डाउनलोड करें।'))){const locale=state.locale;state=fresh();state.locale=locale;save();render();}});}
window.addEventListener('beforeunload',e=>{if(session&&!session.done){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session?.timed&&!session.done)runTimer();});
render();
